def are_equivalent(a, b):
    def divisor_sum(n):
        total = 1  # start with 1, since 1 is always a proper divisor
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total
    return divisor_sum(a) == divisor_sum(b)
